B.a0B=new A.T(61326,"MaterialIcons",null,!1)
B.afJ=new A.as(B.a0B,"Detaliile bancare sunt colectate de Stripe \u0219i nu sunt stocate pe serverele noastre.")
B.aft=new A.as(B.ic,"Po\u021bi cere oric\xe2nd \u0219tergerea permanent\u0103 a contului \u0219i a datelor asociate.")
